import React from "react";
import { useNavigate } from "react-router-dom";
import {
  FaJava,
  FaPython,
  FaDatabase,
  FaChartLine,
  FaLaptopCode,
  FaReact
} from "react-icons/fa";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">
      <div className="container">

        {/* LEFT SIDE */}
        {/* LEFT SIDE */}
<div className="left">

  <div className="introCard">

    <p className="tag">WELCOME TO MY PORTFOLIO</p>

    <h1>
      Hi, I'm <span className="name">Swetha A</span>
    </h1>

    <div className="highlightLine"></div>

    <h2 className="role">
      Full Stack Developer <span>•</span> System Builder <span>•</span> UI Thinker
    </h2>

    <p className="desc">
      I specialize in designing structured systems and building scalable web applications
      where performance, logic, and clean UI work together seamlessly.
    </p>

    <div className="stats">
      <div>
        <h3>10+</h3>
        <p>Projects</p>
      </div>
      <div>
        <h3>5★</h3>
        <p>UI Focus</p>
      </div>
      <div>
        <h3>Full</h3>
        <p>Stack Dev</p>
      </div>
    </div>

    <div className="buttons">
      <button className="btn primary" onClick={() => navigate("/projects")}>
        🚀 Explore Projects
      </button>
      <button className="btn secondary" onClick={() => navigate("/about")}>
        👩‍💻 About Me
      </button>
    </div>

  </div>

</div>

        {/* RIGHT SIDE */}
        <div className="right">
          <div className="radar">

            {/* GLOW */}
            <div className="glow"></div>

            {/* RINGS */}
            <div className="ring r1"></div>
            <div className="ring r2"></div>
            <div className="ring r3"></div>

            {/* SCAN */}
            <div className="sweep"></div>

            {/* CENTER GIRL WITH LAPTOP */}
            <div className="center">
              <img
                src="https://cdn-icons-png.flaticon.com/512/3893/3893079.png"
                alt="girl working on laptop"
              />
            </div>

            {/* ORBIT ICONS */}
            <div className="orbit o1"><FaJava /></div>
            <div className="orbit o2"><FaPython /></div>
            <div className="orbit o3"><FaDatabase /></div>
            <div className="orbit o4"><FaChartLine /></div>
            <div className="orbit o5"><FaLaptopCode /></div>

            {/* NEW REACT ICON */}
            <div className="orbit o6"><FaReact /></div>

            {/* PARTICLES */}
            <span className="particle p1"></span>
            <span className="particle p2"></span>
            <span className="particle p3"></span>
            <span className="particle p4"></span>
            <span className="particle p5"></span>
            <span className="particle p6"></span>

          </div>
        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 6%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.3fr 1fr;
          gap: 40px;
          width: 100%;
          align-items: center;
        }

       /* LEFT SIDE - CLEAN TYPOGRAPHY STYLE */

.left {
  display: flex;
  flex-direction: column;
  justify-content: center;
  font-family: "Philosopher", sans-serif;
}

/* TAG */
.tag {
  font-size: 12px;
  letter-spacing: 5px;
  color: #64748b;
  margin-bottom: 10px;
}

/* NAME */
h1 {
  font-size: 64px;
  font-weight: 700;
  margin: 0;
  color: #e2e8f0;
  line-height: 1.1;
}

.name {
  color: #38BDF8;
}

/* ROLE */
.role {
  font-size: 18px;
  font-weight: 400;
  margin-top: 12px;
  color: #94a3b8;
}

/* DESCRIPTION */
.desc {
  margin-top: 20px;
  font-size: 16px;
  line-height: 1.8;
  color: #cbd5e1;
  max-width: 520px;
}

/* BUTTONS */
.buttons {
  margin-top: 30px;
  display: flex;
  gap: 15px;
}

.btn {
  padding: 12px 20px;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 500;
  transition: 0.3s ease;
  border: 1px solid rgba(56,189,248,0.3);
}

/* PRIMARY */
.primary {
  background: #38BDF8;
  color: #0b1220;
}

.primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 20px rgba(56,189,248,0.3);
}

/* SECONDARY */
.secondary {
  background: transparent;
  color: #38BDF8;
}

.secondary:hover {
  background: rgba(56,189,248,0.08);
}
        /* RADAR */
